using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = "cs", Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = "math", Name = "Mathematics", Abbreviation = "MATH", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = "phys", Name = "Physics", Abbreviation = "PHYS", Description = "Exploration of matter, energy, and the fundamental forces of nature." },
            new() { Id = "eng", Name = "English", Abbreviation = "ENG", Description = "Literature, writing, and language studies." },
            new() { Id = "hist", Name = "History", Abbreviation = "HIST", Description = "Study of past events and civilizations." },
            new() { Id = "bio", Name = "Biology", Abbreviation = "BIO", Description = "Study of living organisms and life processes." },
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = "cs101", DepartmentId = "cs", CourseCode = "CS 101", Title = "Introduction to Programming",
                Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201",
                Instructor = new() { Name = "Dr. Alice Chen", Title = "Associate Professor", Email = "achen@university.edu", Bio = "Dr. Chen specializes in programming education and has published extensively on introductory CS pedagogy. She received her PhD from MIT.", OfficeHours = "Tue/Thu 2:00–4:00 PM" },
                IsFeatured = true
            },
            new()
            {
                Id = "cs301", DepartmentId = "cs", CourseCode = "CS 301", Title = "Data Structures & Algorithms",
                Description = "In-depth study of data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming, greedy algorithms).",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Hall 305",
                Instructor = new() { Name = "Dr. Marcus Rivera", Title = "Professor", Email = "mrivera@university.edu", Bio = "Dr. Rivera's research focuses on algorithmic complexity and optimization. He has 20 years of teaching experience.", OfficeHours = "Mon/Wed 1:00–3:00 PM" },
                IsFeatured = false
            },
            new()
            {
                Id = "cs420", DepartmentId = "cs", CourseCode = "CS 420", Title = "Machine Learning",
                Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation techniques.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Building 110",
                Instructor = new() { Name = "Dr. Priya Patel", Title = "Assistant Professor", Email = "ppatel@university.edu", Bio = "Dr. Patel joined the faculty after working at a leading AI research lab. Her work focuses on deep learning and NLP.", OfficeHours = "Fri 10:00 AM–12:00 PM" },
                IsFeatured = true
            },
            new()
            {
                Id = "math201", DepartmentId = "math", CourseCode = "MATH 201", Title = "Linear Algebra",
                Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors with applications.",
                Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 102",
                Instructor = new() { Name = "Dr. James Okafor", Title = "Professor", Email = "jokafor@university.edu", Bio = "Dr. Okafor is an award-winning educator whose research spans algebraic topology and applied mathematics.", OfficeHours = "Tue/Thu 10:00 AM–12:00 PM" },
                IsFeatured = false
            },
            new()
            {
                Id = "math310", DepartmentId = "math", CourseCode = "MATH 310", Title = "Probability & Statistics",
                Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis. Applications to real-world data sets.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Building 205",
                Instructor = new() { Name = "Dr. Sarah Kim", Title = "Associate Professor", Email = "skim@university.edu", Bio = "Dr. Kim's research focuses on Bayesian statistics and its applications in biomedical research.", OfficeHours = "Mon/Wed 3:00–5:00 PM" },
                IsFeatured = true
            },
            new()
            {
                Id = "phys101", DepartmentId = "phys", CourseCode = "PHYS 101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Calculus-based approach with weekly lab sessions.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", Location = "Physics Lab 101",
                Instructor = new() { Name = "Dr. Robert Tanaka", Title = "Professor", Email = "rtanaka@university.edu", Bio = "Dr. Tanaka is a Fellow of the American Physical Society with research in condensed matter physics.", OfficeHours = "Tue 1:00–3:00 PM" },
                IsFeatured = false
            },
            new()
            {
                Id = "eng210", DepartmentId = "eng", CourseCode = "ENG 210", Title = "Creative Writing",
                Description = "Workshop-based course covering fiction, poetry, and creative nonfiction. Students develop a portfolio of original work.",
                Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Humanities 308",
                Instructor = new() { Name = "Prof. Maria Santos", Title = "Senior Lecturer", Email = "msantos@university.edu", Bio = "Prof. Santos is a published novelist and poet. Her work has appeared in The New Yorker and The Paris Review.", OfficeHours = "Wed 1:00–4:00 PM" },
                IsFeatured = true
            },
            new()
            {
                Id = "hist150", DepartmentId = "hist", CourseCode = "HIST 150", Title = "World History: 1500 to Present",
                Description = "Survey of global historical developments from the Age of Exploration to the modern era, covering political, social, and cultural transformations.",
                Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", Location = "Liberal Arts 204",
                Instructor = new() { Name = "Dr. Eleanor Wright", Title = "Associate Professor", Email = "ewright@university.edu", Bio = "Dr. Wright specializes in modern European and global history with a focus on colonialism and its legacies.", OfficeHours = "Thu 10:00 AM–12:00 PM" },
                IsFeatured = false
            },
            new()
            {
                Id = "bio201", DepartmentId = "bio", CourseCode = "BIO 201", Title = "Genetics",
                Description = "Principles of heredity, gene expression, and genetic engineering. Includes laboratory work with model organisms.",
                Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM + Lab Wed 1:00–3:50 PM", Location = "Life Sciences 112",
                Instructor = new() { Name = "Dr. David Nguyen", Title = "Associate Professor", Email = "dnguyen@university.edu", Bio = "Dr. Nguyen's lab studies gene regulation in developmental biology. He received an NSF CAREER award in 2021.", OfficeHours = "Mon 2:00–4:00 PM" },
                IsFeatured = false
            },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(string departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, string? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId == departmentId);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

