@using UniversityCourseCatalog.Models

<div class="card h-100 shadow-sm featured-card">
    <div class="card-body">
        <span class="badge bg-primary mb-2">@Course.CourseCode</span>
        <span class="badge bg-secondary mb-2">@Course.Credits Credits</span>
        <h5 class="card-title">@Course.Title</h5>
        <p class="card-text text-muted">@Truncate(Course.Description, 120)</p>
        <p class="card-text"><small>Instructor: @Course.Instructor.Name</small></p>
    </div>
    <div class="card-footer bg-transparent">
        <a href="courses/@Course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = default!;

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@using UniversityCourseCatalog.Models

<a href="catalog?department=@Department.Id" class="text-decoration-none">
    <div class="card h-100 border-start border-4 border-primary department-link-card">
        <div class="card-body">
            <h5 class="card-title mb-1">@Department.Name</h5>
            <p class="card-text text-muted small mb-0">@Department.Abbreviation — @Department.Description</p>
        </div>
    </div>
</a>

@code {
    [Parameter, EditorRequired]
    public Department Department { get; set; } = default!;
}

@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services

<form method="get" action="catalog" data-enhance>
    <div class="row g-3 mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <span class="input-group-text">🔍</span>
                <input type="text" name="search" value="@Search" class="form-control" placeholder="Search courses, instructors..." />
            </div>
        </div>
        <div class="col-md-4">
            <select name="department" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in Departments)
                {
                    <option value="@dept.Id" selected="@(dept.Id == Department)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button type="submit" class="btn btn-primary w-100">Filter</button>
        </div>
    </div>
</form>

@code {
    [Parameter] public string? Search { get; set; }
    [Parameter] public string? Department { get; set; }
    [Parameter, EditorRequired] public List<Models.Department> Departments { get; set; } = default!;
}

