@page "/catalog"
@using UniversityCourseCatalog.Components.Shared
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-2">Course Catalog</h1>
<p class="text-muted mb-4">Search and filter courses across all departments.</p>

<CourseFilters Search="@Search" Department="@Department" Departments="departments" />

@if (!string.IsNullOrWhiteSpace(Department))
{
    var dept = Catalog.GetDepartment(Department);
    if (dept is not null)
    {
        <div class="alert alert-info py-2">
            Showing courses in <strong>@dept.Name</strong>
            <a href="catalog" class="ms-2">Clear filter</a>
        </div>
    }
}

@if (courses.Count == 0)
{
    <div class="alert alert-warning">
        No courses found matching your criteria. Try a different search term or department.
    </div>
}
else
{
    <p class="text-muted small mb-3">@courses.Count course(s) found</p>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in courses)
        {
            <div class="col">
                <CourseCard Course="course" />
            </div>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }

    private List<Models.Course> courses = new();
    private List<Models.Department> departments = new();

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.SearchCourses(Search, Department);
    }
}

