@page "/"
@using UniversityCourseCatalog.Components.Shared
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-5 fw-bold">University Course Catalog</h1>
    <p class="lead text-muted">Browse departments, explore courses, and request enrollment — all in one place.</p>
    <a href="catalog" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
    <a href="enroll" class="btn btn-outline-success btn-lg">Request Enrollment</a>
</div>

<h2 class="mb-3">Featured Courses</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4 mb-5">
    @foreach (var course in featuredCourses)
    {
        <div class="col">
            <FeaturedCourseCard Course="course" />
        </div>
    }
</div>

<h2 class="mb-3">Departments</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-3">
    @foreach (var dept in departments)
    {
        <div class="col">
            <DepartmentLinkCard Department="dept" />
        </div>
    }
</div>

@code {
    private List<Models.Course> featuredCourses = new();
    private List<Models.Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }
}

toolArgs.file_text:
@page "/courses/{CourseId}"
@using UniversityCourseCatalog.Components.Shared
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <div class="alert alert-danger">
        <h4>Course Not Found</h4>
        <p>The course you're looking for doesn't exist.</p>
        <a href="catalog" class="btn btn-primary">Back to Catalog</a>
    </div>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="catalog">Catalog</a></li>
            @if (department is not null)
            {
                <li class="breadcrumb-item"><a href="catalog?department=@department.Id">@department.Name</a></li>
            }
            <li class="breadcrumb-item active" aria-current="page">@course.CourseCode</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@course.Title</h1>
            <p class="lead text-muted">@course.CourseCode</p>

            <div class="card mb-4">
                <div class="card-body">
                    <h5 class="card-title">Course Description</h5>
                    <p>@course.Description</p>
                </div>
            </div>

            <InstructorBio Instructor="course.Instructor" />
        </div>

        <div class="col-lg-4">
            <div class="card mb-3">
                <div class="card-header"><h5 class="mb-0">Course Details</h5></div>
                <ul class="list-group list-group-flush">
                    <li class="list-group-item"><strong>Credits:</strong> @course.Credits</li>
                    <li class="list-group-item"><strong>Schedule:</strong> @course.Schedule</li>
                    <li class="list-group-item"><strong>Location:</strong> @course.Location</li>
                    @if (department is not null)
                    {
                        <li class="list-group-item"><strong>Department:</strong> @department.Name</li>
                    }
                </ul>
            </div>

            <a href="enroll?courseId=@course.Id" class="btn btn-success w-100 btn-lg">
                Request Enrollment
            </a>
            <a href="catalog" class="btn btn-outline-secondary w-100 mt-2">
                Back to Catalog
            </a>
        </div>
    </div>
}

@code {
    [Parameter] public string CourseId { get; set; } = string.Empty;

    private Models.Course? course;
    private Models.Department? department;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(CourseId);
        if (course is not null)
        {
            department = Catalog.GetDepartment(course.DepartmentId);
        }
    }
}

